it('produces a new controlled source12 departure over exact E and replays native full/compact', async () => {
  const before11 = replay(prefix.seed, prefix.inputs, prefix.minute, prefix.game);
  const before9 = replay(7, [], 930, 'stairwell@9');
  expect(createHash('sha256').update(canonicalPersona(before11)).digest('hex')).toBe(
    '0a7dafcdd09ed4f1a15b373af8204683411a178513af2e994c413426b9f65d68',
  );
  const api = await import('../src/sim/aligned-visit.ts');
  const stamp = {
    app: '0.1.0',
    framework: '3.0.0',
    commit: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(),
    dirty: execFileSync('git', ['status', '--porcelain'], { encoding: 'utf8' }).trim().length > 0,
  };
  const state = await api.departAlignedVisit(prefix, predecessor, stamp);
  expect(state.world).toEqual(before11);
  expect(state.world.version).toBe('stairwell@11');
  expect(canReplay(state.game)).toBe(false);
  expect(state.inputs).toEqual([{ at: 930, kind: 'aligned-visit-depart' }]);
  expect(state.accepted).toBe(false);
  expect(state.submitted).toBe(false);
  expect(state.departure.revision).not.toBe(predecessor.revision);
  expect(state.departure.parentRevision).toBeNull();
  expect(state.departure.source.rules).toBe('12');
  expect(state.departure.transfer.provenance).toEqual(stamp);
  const complete = state.departure.transfer.complete as { raw: typeof capturedRaw };
  expect(complete.raw).toEqual(capturedRaw);
  expect(new TextEncoder().encode(JSON.stringify(complete.raw)).length).toBe(6023);
  expect(snapshot(restore(complete.raw))).toEqual(capturedRaw);
  await validatePersona(state.departure);
  expect(state.departure.transfer.retainedSchedule).toEqual([
    { role: 'derya', kind: 'night-duty', at: 1170 },
  ]);
  const full = api.exportAlignedVisit(state);
  const compact = api.exportAlignedVisit(state, true);
  expect(await api.importAlignedVisit(JSON.stringify(full))).toEqual(state);
  expect(await api.importAlignedVisit(JSON.stringify(compact))).toEqual(state);
  expect(api.exportAlignedVisit(await api.replayAlignedVisit(compact))).toEqual(full);
  // Valid public rehashes must not substitute the immutable capture, even together.
  const replacement = structuredClone(compact);
  const { revision: _oldRevision, ...replacementBody } = replacement.predecessor;
  replacementBody.branchId = 'substituted-capture-branch';
  replacementBody.source.build = '000000000000';
  (replacementBody.transfer.life as { skipped: number }).skipped = 1;
  replacement.predecessor = await createPersona(replacementBody);
  replacement.prefix.oneCast!.rows = [{ changed: 'serializable source world' }] as never;
  const changedTransfer = replacement.departure.transfer;
  changedTransfer.life = structuredClone(replacement.predecessor.transfer.life);
  const visit = changedTransfer.visit as {
    predecessor: { source: unknown; revision: string; branchId: string; prefixSHA256: string };
    departureBranchId: string;
  };
  Object.assign(visit.predecessor, {
    source: replacement.predecessor.source,
    revision: replacement.predecessor.revision,
    branchId: replacement.predecessor.branchId,
    prefixSHA256: createHash('sha256').update(canonicalPersona(replacement.prefix)).digest('hex'),
  });
  visit.departureBranchId = replacement.predecessor.branchId;
  const { revision: _departureRevision, ...departureBody } = replacement.departure;
  departureBody.branchId = replacement.predecessor.branchId;
  replacement.departure = await createPersona(departureBody);
  await validatePersona(replacement.predecessor);
  await validatePersona(replacement.departure);
  expect(replacement.predecessor.transfer.checkpoint).toEqual(predecessor.transfer.checkpoint);
  const replacementBefore = structuredClone(replacement);
  const originalBefore = structuredClone({ prefix, predecessor, capturedRaw });
  const substitutions = await Promise.allSettled([
    api.departAlignedVisit(prefix, replacement.predecessor, stamp),
    api.departAlignedVisit(replacement.prefix, predecessor, stamp),
    api.replayAlignedVisit(replacement),
  ]);
  expect(replacement).toEqual(replacementBefore);
  expect({ prefix, predecessor, capturedRaw }).toEqual(originalBefore);
  expect(substitutions.map((result) => result.status)).toEqual(['rejected', 'rejected', 'rejected']);
  const failures: { name: string; error: string }[] = [];
  const reject = async (name: string, run: () => Promise<unknown>) => {
    try {
      await run();
      throw new Error('UNEXPECTED_ACCEPTANCE');
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      expect(message).not.toBe('UNEXPECTED_ACCEPTANCE');
      failures.push({ name, error: message });
    }
  };
  for (const change of [
    'raw',
    'missing raw',
    'checkpoint',
    'hostObligations',
    'dialect',
    'phase',
    'prefix',
    'schedule',
    'branch',
  ]) {
    const changed = structuredClone(compact);
    const transfer = changed.departure.transfer;
    if (change === 'raw') (transfer.complete as { raw: typeof capturedRaw }).raw.body.health = 0.8;
    if (change === 'missing raw') delete transfer.complete;
    if (change === 'dialect') transfer.castPassport = 'unknown/1';
    if (change === 'checkpoint') (transfer.checkpoint as { sourceMinute: number }).sourceMinute = 931;
    if (change === 'hostObligations') delete transfer.hostObligations;
    if (change === 'phase') transfer.phase = 'garden-closing';
    if (change === 'prefix') changed.prefix.inputs = [{ kind: 'cast-pause', who: 'derya', at: 421 }];
    if (change === 'schedule') transfer.retainedSchedule = [];
    if (change === 'branch') changed.departure.branchId = 'foreign-branch';
    // Recompute the public envelope hash: semantic checks must refuse even a valid envelope.
    const { revision: _revision, ...body } = changed.departure;
    changed.departure = await createPersona(body);
    await reject(change, () => api.replayAlignedVisit(changed));
  }
  await reject('unsafe JSON', () =>
    api.importAlignedVisit(
      JSON.stringify(compact).replace('"phase":"departure"', '"phase":"departure","__proto__":{}'),
    ),
  );
  const changedFull = structuredClone(full);
  if (changedFull.state) changedFull.state.world.k.money++;
  await reject('changed derived world', () => api.replayAlignedVisit(changedFull));
  expect(replay(prefix.seed, prefix.inputs, prefix.minute, prefix.game)).toEqual(before11);
  expect(replay(7, [], 930, 'stairwell@9')).toEqual(before9);
  expect(snapshot(personOf(before11, 'derya'))).toEqual(capturedRaw);
  const directory = process.env.DERYA_SOURCE12_PROOFS;
  if (directory) {
    mkdirSync(directory, { recursive: true });
    for (const [name, value] of Object.entries({
      full,
      compact,
      packet: state.departure,
      predecessor,
      prefix,
      raw: complete.raw,
      failures,
      substitutions: substitutions.map((result, index) => ({
        name: ['predecessor branch/life/build', 'prefix oneCast rows', 'coordinated replay'][index],
        status: result.status,
        error: result.status === 'rejected' ? String(result.reason) : null,
      })),
      baseline9: before9,
      baseline11: before11,
    }))
      writeFileSync(join(directory, `${name}.json`), `${JSON.stringify(value, null, 2)}\n`);
  }
});

