const digest = (value: unknown) => createHash('sha256').update(canonicalPersona(value)).digest('hex');
it('returns exact Garden raw against the same paused legacy11 prefix in every field', async () => {
  const api = await import('../src/sim/aligned-visit.ts');
  const before9 = replay(7, [], 990, 'stairwell@9');
  const before13 = replay(7, [], 990, 'stairwell@13');
  const departed = await api.departAlignedVisit(prefix, predecessor, originalStamp);
  const departureCompact = api.exportAlignedVisit(departed, true);
  const argsBefore = structuredClone({ departureCompact, gardenCapture });
  const legacy = replay(prefix.seed, prefix.inputs, 990, prefix.game);
  legacy.oneCast = structuredClone(prefix.oneCast);
  // This constant comes from retained original-E source, run independently outside this module.
  expect(digest(legacy)).toBe('532022648f335042a240d722874daa907581009be52ab9641438839374a722b2');
  expect(snapshot(personOf(legacy, 'derya'))).toEqual(capturedRaw);
  const absence = structuredClone(departed.world);
  for (let minute = 931; minute <= 990; minute++) {
    step(absence);
    expect(absence.minute).toBe(minute);
    expect(snapshot(personOf(absence, 'derya'))).toEqual(capturedRaw);
  }
  expect(absence).toEqual(legacy);
  const garden = await replayGardenVisit(gardenCapture);
  const gardenFull = await exportGardenVisit(garden);
  await validateGardenVisitSave(gardenCapture);
  expect(await importGardenVisit(JSON.stringify(gardenFull))).toEqual(garden);
  const raw = snapshot(garden.people.derya);
  expect(digest(raw)).toBe('145465eed9e13433e650ba14f7d5b908998d8c6894793f6907e894b32b75a041');
  const returned = await api.returnAlignedVisit(departureCompact, gardenCapture);
  expect(await api.returnAlignedVisit(departureCompact, gardenFull)).toEqual(returned);
  expect({ departureCompact, gardenCapture }).toEqual(argsBefore);
  // All fields stay equal except precisely one raw slot and the declared host presence fields.
  const expected = structuredClone(legacy);
  expected.people[expected.people.findIndex((person) => person.id === 'derya')] = restore(raw);
  delete expected.castPauses!.derya;
  Object.assign(rOf(expected, 'derya'), { where: 'home', doing: 'home', until: 990, stairsUntil: 0 });
  expect(returned.world).toEqual(expected);
  expect(snapshot(personOf(returned.world, 'derya'))).toEqual(raw);
  expect(snapshot(restore(raw))).toEqual(raw);
  expect(canReplay(returned.game)).toBe(false);
  expect(returned.accepted).toBe(false);
  expect(returned.submitted).toBe(false);
  expect(returned.provenance).toEqual(originalStamp);
  expect(returned.departure).toEqual(departed.departure);
  const full = api.exportAlignedVisit(returned);
  const compact = api.exportAlignedVisit(returned, true);
  const savedBefore = structuredClone({ full, compact });
  for (const save of [full, compact]) {
    expect(await api.replayAlignedVisit(save)).toEqual(returned);
    expect(await api.importAlignedVisit(JSON.stringify(save))).toEqual(returned);
    expect(api.exportAlignedVisit(await api.replayAlignedVisit(save))).toEqual(full);
  }
  expect({ full, compact }).toEqual(savedBefore);
  const { external: _external, state: _state, ...metadata } = full;
  boundedPersonaJson(metadata);
  // Measure the real combined chapter; it is a native file, not a Shelf transfer.
  expect(checkRun(JSON.stringify(full))).toBe(true);
  expect(() => boundedPersonaJson(full)).toThrow();
  const continued = structuredClone(returned.world);
  step(continued);
  expect(personOf(continued, 'derya').now).toBe(991);
  while (continued.minute < 1170) step(continued);
  expect(continued.minute).toBe(1170);
  // At1170 the existing host still honors the ongoing meal interval. Do not force work.
  expect(rOf(continued, 'derya').doing).toBe('meal');
  expect(personOf(continued, 'derya').now).toBe(1141);
  const dutyBoundary = rOf(continued, 'derya').until;
  expect(dutyBoundary).toBeGreaterThan(1170);
  while (continued.minute < dutyBoundary) step(continued);
  expect(rOf(continued, 'derya').doing).toBe('work');
  expect(personOf(continued, 'derya').activity?.affordanceId).toBe('derya-night-work');
  expect(returned.world).toEqual(expected);
  expect(replay(7, [], 990, 'stairwell@9')).toEqual(before9);
  expect(replay(7, [], 990, 'stairwell@13')).toEqual(before13);
  expect(api.exportAlignedVisit(await api.replayAlignedVisit(departureCompact), true)).toEqual(
    departureCompact,
  );
  const directory = process.env.DERYA_RETURN_PROOFS;
  if (directory) {
    mkdirSync(directory, { recursive: true });
    const metrics = (value: unknown) => {
      let nodes = 0,
        depth = 0;
      const visit = (v: unknown, d: number) => {
        nodes++;
        depth = Math.max(depth, d);
        if (v && typeof v === 'object') for (const child of Object.values(v)) visit(child, d + 1);
      };
      visit(value, 0);
      return { bytes: Buffer.byteLength(JSON.stringify(value)), nodes, depth, sha256: digest(value) };
    };
    for (const [name, value] of Object.entries({
      full,
      compact,
      legacy,
      continued,
      raw,
      limits: {
        full: metrics(full),
        compact: metrics(compact),
        metadata: metrics(metadata),
        gardenCompact: metrics(gardenCapture),
        gardenFull: metrics(gardenFull),
        nativeBytes: 4194304,
        nativeDepth: 64,
        nativeContainers: 60000,
        nativeTokens: 480000,
        metadataBytes: 262144,
        metadataNodes: 20000,
        metadataDepth: 24,
      },
    }))
      writeFileSync(join(directory, `${name}.json`), JSON.stringify(value, null, 2) + '\n');
  }
});
it('refuses invalid finite returns before installation through direct and JSON paths', async () => {
  const api = await import('../src/sim/aligned-visit.ts');
  const departure = api.exportAlignedVisit(
    await api.departAlignedVisit(prefix, predecessor, originalStamp),
    true,
  );
  const returned = await api.returnAlignedVisit(departure, gardenCapture);
  const compact = api.exportAlignedVisit(returned, true);
  const failures: { name: string; error: string }[] = [];
  const rejectBoth = async (name: string, value: unknown) => {
    const before = structuredClone(value);
    for (const [path, call] of [
      ['direct', () => api.replayAlignedVisit(value)],
      ['JSON', () => api.importAlignedVisit(JSON.stringify(value))],
    ] as const) {
      try {
        await call();
        throw new Error('UNEXPECTED_ACCEPTANCE');
      } catch (error) {
        expect(String(error)).not.toContain('UNEXPECTED_ACCEPTANCE');
        failures.push({ name: name + ' ' + path, error: String(error) });
      }
      expect(value).toEqual(before);
    }
  };
  const ref = Object.keys(compact.external!)[0]!;
  // Focused structural refusals. Published Garden independently authenticates all graph fields.
  for (const name of [
    'unknown',
    'duplicate',
    'missing',
    'extra',
    'late',
    'wrong clock',
    'wrong branch',
    'forged raw',
    'missing raw',
    'forged claim',
    'dirty stamp',
    'open',
    'unsafe',
    'oversized',
    'depth',
  ]) {
    const changed = structuredClone(compact);
    const garden = changed.external![ref]!;
    if (name === 'unknown') Object.assign(changed, { unknown: true });
    if (name === 'duplicate') (changed.inputs as unknown[]).push(structuredClone(changed.inputs[1]));
    if (name === 'missing') delete changed.external;
    if (name === 'extra') changed.external!.extra = garden;
    if (name === 'late') changed.inputs[1]!.at = 1170 as never;
    if (name === 'wrong clock') garden.actualEnd = 991;
    if (name === 'wrong branch')
      (garden.resources[garden.source.packet] as { branchId: string }).branchId = 'wrong';
    if (name === 'forged raw') (garden.resources[garden.source.raw] as { now: number }).now = 931;
    if (name === 'missing raw') delete garden.resources[garden.source.raw];
    if (name === 'forged claim')
      Object.assign(garden.resources[garden.closing!] as object, { rawRef: garden.source.raw });
    if (name === 'dirty stamp') changed.provenance.dirty = false;
    if (name === 'open') {
      garden.phase = 'visiting';
      garden.closing = null;
    }
    if (name === 'unsafe') Object.defineProperty(changed, '__proto__', { value: {}, enumerable: true });
    if (name === 'oversized') Object.assign(changed, { padding: 'x'.repeat(4194304) });
    if (name === 'depth') {
      let deep: unknown = 0;
      for (let i = 0; i < 70; i++) deep = [deep];
      Object.assign(changed, { deep });
    }
    // Rehash the chapter ref so Garden semantics, rather than the outer digest, reject it.
    if (['wrong clock', 'wrong branch', 'forged raw', 'missing raw', 'forged claim', 'open'].includes(name)) {
      const newRef = digest(garden);
      changed.external = { [newRef]: garden };
      Object.assign(changed.inputs[1]!, { gardenRef: newRef });
    }
    await rejectBoth(name, changed);
  }
  const full = api.exportAlignedVisit(returned);
  full.state!.world.k.money++;
  await rejectBoth('full world mismatch', full);
  const before = structuredClone({ departure, gardenCapture });
  await expect(api.returnAlignedVisit(compact, gardenCapture)).rejects.toThrow('duplicate');
  const forged = structuredClone(gardenCapture);
  forged.actualEnd = 1170;
  const forgedBefore = structuredClone(forged);
  await expect(api.returnAlignedVisit(departure, forged)).rejects.toThrow();
  expect(forged).toEqual(forgedBefore);
  expect({ departure, gardenCapture }).toEqual(before);
  const directory = process.env.DERYA_RETURN_PROOFS;
  if (directory) writeFileSync(join(directory, 'refusals.json'), JSON.stringify(failures, null, 2) + '\n');
});
